    clr     d2                              # d2 = row
    cmp     d2, d3
    ble     Draw2BpFile_Impl_RowsDone       # no rows: only when height <= 0 (y is not tested)
    movhu   (0x34, sp), d0
    exth    d0
    mov     d0, (0x24, sp)                  # (0x24,sp) = stride
    movhu   (0x36, sp), d0
    exth    d0
