    mov     (0x30, sp), a0
    movhu   (a0), d0
    movhu   d0, (0x476, sp)                 # rect.top = y
    mov     (0x494, sp), a0
    movhu   (a0), d0
    movhu   d0, (0x474, sp)                 # rect.left = x
    movhu   (a0), d1
